import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"Dependency and artifact audit","description":"","frontmatter":{},"headers":[],"relativePath":"dependency-audit.md","filePath":"dependency-audit.md","lastUpdated":1785242125000}`),a={name:`dependency-audit.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="dependency-and-artifact-audit" tabindex="-1">Dependency and artifact audit <a class="header-anchor" href="#dependency-and-artifact-audit" aria-label="Permalink to “Dependency and artifact audit”">​</a></h1><p>The release policy keeps every duplicated Rust dependency and local crate override explicit. CI also records size budgets for the three executable delivery surfaces. The machine-readable source of truth is <a href="../audits/release-policy.json"><code>audits/release-policy.json</code></a>.</p><h2 id="duplicate-dependency-decisions" tabindex="-1">Duplicate dependency decisions <a class="header-anchor" href="#duplicate-dependency-decisions" aria-label="Permalink to “Duplicate dependency decisions”">​</a></h2><p>The audit recorded on 2026-07-28 found five duplicate groups:</p><table tabindex="0"><thead><tr><th>Dependency</th><th>Versions</th><th>Decision</th><th>Replacement condition</th></tr></thead><tbody><tr><td><code>brotli</code></td><td>7.0.0 / 8.0.4</td><td>Retain</td><td>Remove v7 with the patched WOFF2 decoder chain.</td></tr><tr><td><code>brotli-decompressor</code></td><td>4.0.3 / 5.0.3</td><td>Retain</td><td>Remove v4 with Brotli v7.</td></tr><tr><td><code>thiserror</code></td><td>1.0.69 / 2.0.18</td><td>Retain</td><td>Remove v1 with the two WOFF2 compatibility crates.</td></tr><tr><td><code>thiserror-impl</code></td><td>1.0.69 / 2.0.18</td><td>Retain</td><td>Follows the reviewed <code>thiserror</code> versions.</td></tr><tr><td><code>unicode-width</code></td><td>0.1.14 / 0.2.2</td><td>Retain</td><td>Wait for the <code>miette</code>/<code>textwrap</code> chain to unify without changing diagnostics.</td></tr></tbody></table><p>The owner for every decision is the fontmin-rs maintainers. The dependency gate fails if a new duplicate appears, a recorded version changes, or a duplicate disappears without its retained decision being removed.</p><h2 id="vendored-patch-decisions" tabindex="-1">Vendored patch decisions <a class="header-anchor" href="#vendored-patch-decisions" aria-label="Permalink to “Vendored patch decisions”">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Upstream</th><th>Decision and exit</th></tr></thead><tbody><tr><td><code>allsorts</code> 0.17.0</td><td><a href="https://github.com/yeslogic/allsorts" target="_blank" rel="noreferrer">yeslogic/allsorts</a></td><td>Retain the CFF INDEX and <code>endchar</code> corrections until an upstream release contains equivalent behavior and the permanent regression corpus passes.</td></tr><tr><td><code>safer-bytes</code> 0.2.0</td><td><a href="https://github.com/danieleades/safer-bytes" target="_blank" rel="noreferrer">danieleades/safer-bytes</a></td><td>Retain the stable-Rust compatibility copy until the selected WOFF2 decoder no longer requires it.</td></tr><tr><td><code>woff2-patched</code> 0.4.0</td><td><a href="https://github.com/zimond/woff2-rs" target="_blank" rel="noreferrer">zimond/woff2-rs</a></td><td>Retain explicit coordinate wrapping until an upstream release or owned decoder passes every WOFF2 regression.</td></tr></tbody></table><p>Each override has patch notes beside its source. The audit verifies that the root Cargo patch, notes, owner, upstream, decision, and removal condition remain present together.</p><h2 id="release-artifact-budgets" tabindex="-1">Release artifact budgets <a class="header-anchor" href="#release-artifact-budgets" aria-label="Permalink to “Release artifact budgets”">​</a></h2><p>Release builds use thin LTO, one codegen unit, and stripped symbols. The budgets are intentionally portable across the supported CI platforms:</p><table tabindex="0"><thead><tr><th>Artifact</th><th style="text-align:right;">Budget</th></tr></thead><tbody><tr><td>Rust CLI</td><td style="text-align:right;">8 MiB</td></tr><tr><td>Native Node binding</td><td style="text-align:right;">8 MiB</td></tr><tr><td>Browser WASM binary</td><td style="text-align:right;">4 MiB</td></tr></tbody></table><p>On macOS arm64 after the release-profile change, the local measurements were 4,425,520 bytes for the CLI, 3,279,968 bytes for the native binding, and 2,964,395 bytes for WASM. CI writes its platform measurements to <code>audits/artifact-current.json</code> and uploads the report even alongside the performance reports.</p><p>Run the policy-only check with:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Build and measure all release surfaces with:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:artifacts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Artifact budget failures persist the complete report before exiting, so the responsible delivery surface and measured bytes remain available for review.</p>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};